CREATE TABLE farms (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, manager_user_id BIGINT UNSIGNED NULL, name VARCHAR(200) NOT NULL, location VARCHAR(255) NULL, area_hectares DECIMAL(15,2) NULL, status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_farms_name (name), KEY idx_farms_manager (manager_user_id), CONSTRAINT chk_farms_area CHECK (area_hectares IS NULL OR area_hectares >= 0), CONSTRAINT fk_farms_manager FOREIGN KEY (manager_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
